import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"よくある問題対照表","description":"MiniTavern と Ollama/LM Studio の測連失敗、タイムアウト、CORS、ファイアウォールなどの対照と対処。","frontmatter":{"title":"よくある問題対照表","description":"MiniTavern と Ollama/LM Studio の測連失敗、タイムアウト、CORS、ファイアウォールなどの対照と対処。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"よくある問題対照表 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern と Ollama/LM Studio の測連失敗、タイムアウト、CORS、ファイアウォールなどの対照と対処。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/troubleshoot"}]]},"headers":[],"relativePath":"ja/troubleshoot.md","filePath":"ja/troubleshoot.md","lastUpdated":1787224147000}'),o={name:"ja/troubleshoot.md"};function l(i,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="よくある問題対照表" tabindex="-1">よくある問題対照表 <a class="header-anchor" href="#よくある問題対照表" aria-label="Permalink to &quot;よくある問題対照表&quot;">​</a></h1><p>現象から探す；まだだめなら App <strong>設定 → ヘルプとフィードバック → 問題フィードバック</strong>（スクショと問題ログ可）、または <strong>フィードバックメール</strong>。できるだけ：OS、ツール（Ollama／LM Studio／KoboldCPP など）、Base URL（IP 末二段は伏せ可）、エラー原文を書く。</p><h2 id="接続-測連" tabindex="-1">接続／測連 <a class="header-anchor" href="#接続-測連" aria-label="Permalink to &quot;接続／測連&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>ありうる原因</th><th>対処</th></tr></thead><tbody><tr><td>接続タイムアウト</td><td>同一 Wi‑Fi でない、ファイアウォールがポート遮断、サービスが <code>0.0.0.0</code> をリスンしていない</td><td>同網を確認；ポート開放；各ツールの「サービス／LAN」章に従う</td></tr><tr><td>すぐ失敗／接続不可</td><td>IP 誤り、ポート誤り、サービス未起動</td><td>PC ブラウザで先に <code>http://IP:ポート/v1/models</code>；Base URL を照合</td></tr><tr><td>localhost を入れても失敗</td><td>スマホの localhost はスマホ自身</td><td>PC の LAN IP に変更</td></tr><tr><td>401／鍵エラー</td><td>一部ローカルスタックが Key を検証</td><td>任意の非空プレースホルダ、またはツール文書どおり認証オフ</td></tr><tr><td>404／モデル不存在</td><td>モデル名がローカルと不一致</td><td><code>ollama list</code> または各ツール <code>/v1/models</code> から <strong>完全 id</strong> をコピー</td></tr><tr><td>応答はあるがチャット空白／エラー</td><td>互換性、タイムアウト過短、モデル未ロード</td><td>タイムアウト延長；モデルが load 済みか；小さめモデルで通路検証</td></tr></tbody></table><h2 id="ネットワークとシステム" tabindex="-1">ネットワークとシステム <a class="header-anchor" href="#ネットワークとシステム" aria-label="Permalink to &quot;ネットワークとシステム&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>ありうる原因</th><th>対処</th></tr></thead><tbody><tr><td>PC は可、スマホ不可</td><td>ゲスト Wi‑Fi 隔離、AP 隔離</td><td>主ネットワークへ；一時的にスマホテザリングで PC を接続して試す</td></tr><tr><td>断続的に切れる</td><td>PC スリープ、IP 変化</td><td>スリープ禁止；IP を再確認し接続を更新</td></tr><tr><td>VPN オンで異常</td><td>分流／仮想 NIC</td><td>テスト時は VPN オフ、または LAN を除外</td></tr></tbody></table><h2 id="url-の書き方" tabindex="-1">URL の書き方 <a class="header-anchor" href="#url-の書き方" aria-label="Permalink to &quot;URL の書き方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>正しい例</th><th>誤りの例</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code>（ローカルで証明書未設定なら無理に https しない）</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="http-平文" tabindex="-1">HTTP 平文 <a class="header-anchor" href="#http-平文" aria-label="Permalink to &quot;HTTP 平文&quot;">​</a></h2><p>MiniTavern <strong>Android</strong> は平文 HTTP（LAN でよく使う）を許可済み。まだ遮断される場合：</p><ul><li>Base URL が <code>http://</code> で誤ったプロトコルでないか</li><li>システム／メーカーのネットワーク保護が LAN を遮断していないか</li><li>iOS で ATS 制限に当たる場合は、文書どおりの LAN アドレスを優先；だめなら OS バージョンとエラーをフィードバック</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>ブラウザのウェブページがよく CORS 制限を受ける；<strong>ネイティブ App の API 直連は一般に CORS の影響を受けない</strong>。PC ブラウザでフロントページが失敗しても MiniTavern が失敗するとは限らない——App 内測連を正とする。</p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>対処</th></tr></thead><tbody><tr><td>最初の字が極端に遅い</td><td>より小さい量子化／パラメータ；GPU 使用を確認</td></tr><tr><td>生成途中で止まる</td><td>タイムアウト延長；显存を食う他プログラムを閉じる；PC 側ログの OOM を確認</td></tr></tbody></table><h2 id="関連リンク" tabindex="-1">関連リンク <a class="header-anchor" href="#関連リンク" aria-label="Permalink to &quot;関連リンク&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/manual/errors">マニュアル · エラーコード</a>（測連／チャット API エラー）</li><li><a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a></li><li><a href="/ultra_guides/ja/local/tools">ツール一覧</a> · <a href="/ultra_guides/ja/local/models">推奨モデル</a></li><li><a href="/ultra_guides/ja/ollama/lan">Ollama LAN</a></li><li><a href="/ultra_guides/ja/lmstudio/server">LM Studio Local Server</a></li><li><a href="/ultra_guides/ja/koboldcpp/server">KoboldCPP API</a></li><li><a href="/ultra_guides/ja/llamacpp/server">llama.cpp server</a></li><li><a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern 設定</a></li></ul>',17)])])}const b=a(o,[["render",l]]);export{p as __pageData,b as default};
